const execution = $json.execution ?? {};
const trigger = $json.trigger ?? {};
const workflow = $json.workflow ?? {};
const message = execution.error?.message ?? trigger.error?.message ?? trigger.error?.cause?.message ?? 'Unknown workflow failure';
const match = String(message).match(/\[lead_id=([^\]]+)\]/);
const leadId = match?.[1] ?? `execution_${execution.id ?? Date.now()}`;
const context = { lead_id: leadId, correlation_id: leadId, status: 'DEAD_LETTER', approved: null, last_action: 'FAILED', error_count: 1, config: { mock_api_base_url: $env.MOCK_API_BASE_URL || 'http://mock-api:8080' } };
const errorPayload = { timestamp: new Date().toISOString(), lead_id: leadId, workflow_id: workflow.id ?? null, workflow_name: workflow.name ?? null, execution_id: execution.id ?? null, execution_url: execution.url ?? null, last_node: execution.lastNodeExecuted ?? trigger.error?.node?.name ?? null, message, stack: execution.error?.stack ?? trigger.error?.cause?.stack ?? null, retry_of: execution.retryOf ?? null };
return [{ json: { ...context, error_payload: errorPayload, audit_events: [{ step: 'FAILED', status: 'ERROR', message }] } }];
